-- 0004 Blueprint port. Generated by drizzle-kit from src/db/schema.ts, then hand-edited:
--   [hand-edit 1] proposals.kind/title/schema_version: added nullable, backfilled, then SET NOT NULL, so the
--                 migration also succeeds on databases that already hold proposals written under 0002/0003.
--   [hand-edit 2] four composite FKs use column-scoped ON DELETE SET NULL (PostgreSQL 15+):
--                 ai_generations_event_same_org_fk, ai_generations_requested_by_same_org_fk,
--                 proposals_generation_same_org_fk, proposals_requested_by_same_org_fk.
--   [hand-edit 3] REVOKE client write privileges on ai_generations.
-- Enum values added here (proposal_status 'EXPIRED', the survey_question_type answer formats) are not used as
-- enum literals anywhere in this file: drizzle's migrator runs all pending migrations in ONE transaction and
-- PostgreSQL forbids using a newly added enum value before that transaction commits.
CREATE TYPE "public"."ai_generation_status" AS ENUM('STREAMING', 'SUCCEEDED', 'FAILED_VALIDATION', 'FAILED_PROVIDER', 'APPLIED');--> statement-breakpoint
CREATE TYPE "public"."event_phase" AS ENUM('PLAN', 'PREPARE', 'MANAGE', 'RUN', 'ANALYZE', 'IMPROVE');--> statement-breakpoint
CREATE TYPE "public"."kpi_status" AS ENUM('PROPOSED', 'ACTIVE', 'DROPPED');--> statement-breakpoint
CREATE TYPE "public"."organizer_type" AS ENUM('MUNICIPALITY', 'PUBLIC_INSTITUTION', 'UNIVERSITY', 'COMPANY', 'EVENT_AGENCY', 'NONPROFIT', 'OTHER');--> statement-breakpoint
CREATE TYPE "public"."survey_audience" AS ENUM('ATTENDEE', 'SPONSOR', 'EXHIBITOR', 'LOCAL_BUSINESS', 'ORGANIZER', 'RESIDENT', 'PUBLIC_AUTHORITY');--> statement-breakpoint
CREATE TYPE "public"."task_board" AS ENUM('PLANNING', 'OPERATIONS', 'MEASUREMENT');--> statement-breakpoint
CREATE TYPE "public"."task_priority" AS ENUM('CRITICAL', 'HIGH', 'MEDIUM', 'LOW');--> statement-breakpoint
