CREATE TABLE "ai_generations" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"organization_id" uuid NOT NULL,
	"event_id" uuid,
	"requested_by" uuid,
	"kind" text NOT NULL,
	"prompt" text NOT NULL,
	"base_config" jsonb,
	"output" jsonb,
	"validation_errors" jsonb,
	"schema_version" text NOT NULL,
	"provider" text NOT NULL,
	"model" text NOT NULL,
	"temperature" numeric(3, 2) NOT NULL,
	"input_tokens" integer,
	"output_tokens" integer,
	"latency_ms" integer,
	"status" "ai_generation_status" DEFAULT 'STREAMING' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ai_generations_id_organization_id_uq" UNIQUE("id","organization_id"),
	CONSTRAINT "ai_generations_kind_format" CHECK ("ai_generations"."kind" ~ '^[a-z_]+(\.[a-z_]+)?$'),
	CONSTRAINT "ai_generations_schema_version_not_blank" CHECK (length(trim("ai_generations"."schema_version")) > 0),
	CONSTRAINT "ai_generations_temperature_range" CHECK ("ai_generations"."temperature" >= 0 and "ai_generations"."temperature" <= 2)
);
--> statement-breakpoint
