-- [hand-edit 3] RLS decides which rows; privileges decide which operations. ai_generations is written by the
-- server only (adminDb). Client privileges on the other tables are unchanged from 0003: the columns added
-- here are covered by 0003's table-level REVOKE, and tasks keep UPDATE (status, updated_at) only.
REVOKE INSERT, UPDATE, DELETE ON "ai_generations" FROM authenticated, anon;
